        // help
        ["Help"] = "Guida",
        ["Close (F1)"] = "Chiudi (F1)",
        ["Wizard"] = "Procedura guidata",
        ["Coworkee Studio writes an app spec, the JSON the coworkee CLI takes, and lets the CLI create the app. Every page changes one part of the spec; the panel on the left shows where you are and takes you back to any page you have seen."] = "Coworkee Studio scrive una specifica di app, il JSON accettato dalla CLI coworkee, e lascia che la CLI crei l'app. Ogni pagina modifica una parte della specifica; il pannello a sinistra mostra dove ti trovi e ti riporta a qualsiasi pagina già vista.",
        ["Keyboard"] = "Tastiera",
        ["Start options"] = "Opzioni di avvio",
        ["Coworkee Studio in the documentation"] = "Coworkee Studio nella documentazione",
        ["The Studio runs coworkee spec validate and coworkee new --spec. Everything it does works in a terminal as well:"] = "Lo Studio esegue coworkee spec validate e coworkee new --spec. Tutto ciò che fa funziona anche in un terminale:",
        ["All commands and switches"] = "Tutti i comandi e le opzioni",
        ["coworkee mcp runs a Model Context Protocol server over stdio. An AI agent such as Claude Code, Claude Desktop or Copilot in VS Code can then plan an app with you, write its spec, create it and add modules, entities and migrations, with the same commands as this Studio."] = "coworkee mcp esegue un server Model Context Protocol su stdio. Un agente IA come Claude Code, Claude Desktop o Copilot in VS Code può quindi pianificare un'app con te, scriverne la specifica, crearla e aggiungere moduli, entità e migrazioni, con gli stessi comandi di questo Studio.",
        ["This is the MCP server of the command line on your machine. A generated app has its own MCP endpoint under /mcp with the tools of the app (AI assistant module)."] = "Questo è il server MCP della riga di comando sul tuo computer. Un'app generata ha un proprio endpoint MCP in /mcp con gli strumenti dell'app (modulo assistente IA).",
        ["Claude Desktop (claude_desktop_config.json) and other clients with mcpServers"] = "Claude Desktop (claude_desktop_config.json) e altri client con mcpServers",
        ["Tools"] = "Strumenti",
        ["Try it"] = "Provalo",
        ["The agent reads list_options and get_spec_schema, writes a spec with a Sales module, checks it with validate_spec and calls create_app."] = "L'agente legge list_options e get_spec_schema, scrive una specifica con un modulo Sales, la verifica con validate_spec e chiama create_app.",
        ["The MCP server in the documentation"] = "Il server MCP nella documentazione",
        ["Language"] = "Lingua",
        ["Language of the system"] = "Lingua del sistema",
        ["Switch the language"] = "Cambia lingua",
        ["Update available {0}"] = "Aggiornamento disponibile: {0}",
        ["Closes the Studio, updates the coworkee CLI and the Studio, then starts it again. An opened spec is saved first."] = "Chiude lo Studio, aggiorna la CLI coworkee e lo Studio, poi lo riavvia. Una specifica aperta viene salvata prima.",
        ["The update could not start: {0}"] = "Impossibile avviare l'aggiornamento: {0}",
        ["Stop"] = "Arresta",
        ["Start"] = "Avvia",
        ["Stopped"] = "Arrestato",
        ["Aspire dashboard"] = "Dashboard di Aspire",
