        ["Starting the app host…"] = "Avvio dell'app host…",
        ["The app is running"] = "L'app è in esecuzione",
        ["The app host stopped"] = "L'app host si è arrestato",
        ["No app host project below {0}"] = "Nessun progetto app host in {0}",
        ["The app host ended with exit code {0}"] = "L'app host è terminato con il codice di uscita {0}",
        ["Appearance"] = "Aspetto",
        ["coworkee CLI"] = "CLI coworkee",
        ["Empty: the global tool. Or a coworkee executable, or Coworkee.Cli.dll of a local build (runs with dotnet)."] = "Vuoto: il tool globale. Oppure un eseguibile coworkee, o il Coworkee.Cli.dll di una build locale (viene eseguito con dotnet).",
        ["Template source"] = "Origine del template",
        ["A Coworkee.Templates .nupkg or folder instead of nuget.org (coworkee new --template-source), for local builds."] = "Un .nupkg di Coworkee.Templates o una cartella al posto di nuget.org (coworkee new --template-source), per build locali.",
        ["Local package feed"] = "Feed di pacchetti locale",
        ["A folder with local Coworkee packages; the restore of the new app uses it next to nuget.org, and Install CLI looks there too."] = "Una cartella con pacchetti Coworkee locali; il restore della nuova app la usa accanto a nuget.org, e Installa CLI cerca anche lì.",
        ["Settings and recent specs are kept per user in the application data folder (Coworkee/Studio/settings.json)."] = "Le impostazioni e le specifiche recenti sono salvate per utente nella cartella dei dati dell'applicazione (Coworkee/Studio/settings.json).",
        ["Every option of a new app with id, kind, default, choices, pros, cons and when to use it."] = "Ogni opzione di una nuova app con id, tipo, valore predefinito, scelte, pro, contro e quando usarla.",
        ["JSON Schema of the app spec: name, options, branding, modules with entities."] = "JSON Schema della specifica dell'app: nome, opzioni, branding, moduli con entità.",
        ["A complete example spec with options, branding, a module and two entities."] = "Una specifica di esempio completa con opzioni, branding, un modulo e due entità.",
        ["Checks a spec; with a folder also its logo and media files."] = "Verifica una specifica; con una cartella anche il logo e i file multimediali.",
        ["coworkee new from a spec, or from a name and options, in a folder. Takes minutes."] = "coworkee new da una specifica, o da un nome e opzioni, in una cartella. Richiede alcuni minuti.",
        ["A feature module with its first entity: table, permissions, OData set, endpoints, page."] = "Un modulo funzionale con la sua prima entità: tabella, permessi, set OData, endpoint, pagina.",
        ["Another entity in a module created with add_module."] = "Un'altra entità in un modulo creato con add_module.",
        ["An EF Core migration, e.g. after add_module or add_entity."] = "Una migrazione EF Core, ad es. dopo add_module o add_entity.",
        ["Checks the .NET SDK, Docker and dotnet-ef."] = "Verifica .NET SDK, Docker e dotnet-ef.",
        ["Sets the Coworkee package version of the app."] = "Imposta la versione dei pacchetti Coworkee dell'app.",
        ["Searches the Coworkee documentation."] = "Cerca nella documentazione di Coworkee.",
        ["Create an app from switches; coworkee new --spec app.json from a spec."] = "Crea un'app dalle opzioni; coworkee new --spec app.json da una specifica.",
        ["Every switch of coworkee new with pros, cons and when to use it."] = "Ogni opzione di coworkee new con pro, contro e quando usarla.",
        ["Example spec, its JSON Schema, and the check the Studio runs."] = "Specifica di esempio, il suo JSON Schema e la verifica che esegue lo Studio.",
        ["Start the Aspire app host with every service and container."] = "Avvia l'app host Aspire con tutti i servizi e i container.",
        ["Add an EF Core migration to the app."] = "Aggiungi una migrazione EF Core all'app.",
        ["Add a feature module with its first entity."] = "Aggiungi un modulo funzionale con la sua prima entità.",
        ["Add an entity to a module."] = "Aggiungi un'entità a un modulo.",
        ["Move the app to the newest Coworkee packages."] = "Porta l'app ai pacchetti Coworkee più recenti.",
        ["Check SDK, Docker and dotnet-ef."] = "Verifica SDK, Docker e dotnet-ef.",
        ["Install or update and start this Studio."] = "Installa o aggiorna e avvia questo Studio.",
        ["MCP server over stdio for AI agents."] = "Server MCP su stdio per agenti IA.",

        // option catalog of the CLI
        ["Display title in the browser, the app bar, the sign-in pages and the Aspire dashboard (default: the name)."] = "Titolo mostrato nel browser, nella barra dell'app, nelle pagine di accesso e nella dashboard di Aspire (predefinito: il nome).",
        ["Always, when the name is technical (Shop) and users should read something else (Acme Shop)."] = "Sempre, quando il nome è tecnico (Shop) e gli utenti devono leggere altro (Acme Shop).",
        ["Free text with spaces"] = "Testo libero con spazi",
        ["Sample modules"] = "Moduli di esempio",
        ["Catalog (products, brands, dashboard) and Documents modules with their pages, tests and demo data."] = "Moduli Catalog (prodotti, marchi, dashboard) e Documents con le loro pagine, test e dati demo.",
        ["To learn the patterns or to demo the library; switch off for a real app."] = "Per imparare i pattern o mostrare la libreria; disattivalo per un'app reale.",
        ["Working examples of every pattern"] = "Esempi funzionanti di ogni pattern",
        ["Demo data after the first start"] = "Dati demo dopo il primo avvio",
        ["Code you delete later"] = "Codice da eliminare in seguito",
        ["Test projects"] = "Progetti di test",
        ["API, migration, app host and page tests."] = "Test di API, migrazioni, app host e pagine.",
        ["Almost always; leave out only for throw-away prototypes."] = "Quasi sempre; escludili solo per prototipi usa e getta.",
        ["Tests that boot the real app"] = "Test che avviano l'app reale",
        ["A model test that catches missing migrations"] = "Un test del modello che rileva le migrazioni mancanti",
        ["Need Docker to run"] = "Richiedono Docker per l'esecuzione",
        ["Git repository"] = "Repository Git",
        ["Run git init in the new folder."] = "Esegue git init nella nuova cartella.",
        ["When the app becomes its own repository."] = "Quando l'app diventa un repository a sé.",
        ["Ready for the first commit"] = "Pronto per il primo commit",
        ["Not wanted inside an existing repository"] = "Non desiderato all'interno di un repository esistente",
        ["GitHub repository"] = "Repository GitHub",
        ["GitHub repository of the app as owner/repo, e.g. acme/shop: the README gets a QuickRun badge that starts the app from there with one click."] = "Repository GitHub dell'app come owner/repo, ad es. acme/shop: il README riceve un badge QuickRun che avvia l'app da lì con un clic.",
        ["When the app lives on GitHub and others should try it."] = "Quando l'app è su GitHub e altri devono provarla.",
        ["One click from the README to the running app"] = "Un clic dal README all'app in esecuzione",
        ["GitHub only"] = "Solo GitHub",
        ["Audit log"] = "Registro di audit",
        ["Pages for the audit trail, entity history and restore, the security log and the request log of the API. The trail and the security log are always written."] = "Pagine per l'audit trail, la cronologia e il ripristino delle entità, il registro di sicurezza e il registro delle richieste dell'API. L'audit trail e il registro di sicurezza vengono sempre scritti.",
        ["Whenever someone needs to see who changed what."] = "Ogni volta che qualcuno deve vedere chi ha cambiato cosa.",
        ["History and restore per entity"] = "Cronologia e ripristino per entità",
        ["More admin pages"] = "Più pagine di amministrazione",
        ["Requests with headers and bodies"] = "Richieste con intestazioni e corpi",
        ["The request log grows fast (30 days by default)"] = "Il registro delle richieste cresce in fretta (30 giorni per impostazione predefinita)",
        ["Notifications"] = "Notifiche",
        ["In-app notifications with mail digests."] = "Notifiche nell'app con riepiloghi via email.",
        ["When users should hear about changes (comments, chat, own events)."] = "Quando gli utenti devono essere informati delle modifiche (commenti, chat, eventi propri).",
        ["Bell with live updates"] = "Campanella con aggiornamenti dal vivo",
        ["Digest mails"] = "Email di riepilogo",
        ["Tables and a background job"] = "Tabelle e un job in background",
        ["Installable app"] = "App installabile",
        ["Web manifest, service worker and offline page: the app installs on phones and desktops and opens without the browser bar. With notifications users switch on Web Push per device."] = "Web manifest, service worker e pagina offline: l'app si installa su smartphone e desktop e si apre senza la barra del browser. Con le notifiche gli utenti attivano Web Push per dispositivo.",
        ["Almost always; off only when the app must not run as installed app."] = "Quasi sempre; disattivalo solo se l'app non deve funzionare come app installata.",
        ["Installs from the browser like a native app"] = "Si installa dal browser come un'app nativa",
        ["Push notifications on phones and desktops"] = "Notifiche push su smartphone e desktop",
        ["Asks to reload after each deployment"] = "Chiede di ricaricare dopo ogni deployment",
        ["A deployment needs its own VAPID key pair for push"] = "Ogni deployment richiede una propria coppia di chiavi VAPID per le notifiche push",
        ["Chat"] = "Chat",
        ["Direct and group chat with realtime delivery."] = "Chat diretta e di gruppo con consegna in tempo reale.",
        ["Reports"] = "Report",
        ["Dashboards over the OData entity sets with charts, KPIs, tables and filters, aggregated on the server."] = "Dashboard sui set di entità OData con grafici, KPI, tabelle e filtri, aggregati sul server.",
        ["For apps whose users want to see their numbers."] = "Per app i cui utenti vogliono vedere i propri numeri.",
        ["Users build their own dashboards"] = "Gli utenti creano le proprie dashboard",
        ["Shared with roles"] = "Condivise con i ruoli",
        ["A designer page and two tables"] = "Una pagina di progettazione e due tabelle",
        ["For apps where users work together."] = "Per app in cui gli utenti lavorano insieme.",
        ["Built-in communication"] = "Comunicazione integrata",
        ["Not every app needs it"] = "Non tutte le app ne hanno bisogno",
        ["AI assistant"] = "Assistente IA",
        ["Assistant page, MCP endpoint and tool call audit; every permitted command becomes a tool (provider and key in the settings)."] = "Pagina dell'assistente, endpoint MCP e audit delle chiamate agli strumenti; ogni comando consentito diventa uno strumento (provider e chiave nelle impostazioni).",
        ["When users or agents should work with the app in natural language."] = "Quando utenti o agenti devono lavorare con l'app in linguaggio naturale.",
        ["Tools come from the existing commands"] = "Gli strumenti derivano dai comandi esistenti",
        ["MCP endpoint for Claude and other clients"] = "Endpoint MCP per Claude e altri client",
        ["Needs an AI provider to answer"] = "Richiede un provider IA per rispondere",
        ["Database backups"] = "Backup del database",
        ["Backups and restore of the database from the admin pages."] = "Backup e ripristino del database dalle pagine di amministrazione.",
        ["Self-hosted installations without managed database backups."] = "Installazioni self-hosted senza backup gestiti del database.",
        ["Backup and restore without a DBA"] = "Backup e ripristino senza un DBA",
        ["Managed databases bring their own"] = "I database gestiti hanno i propri",
        ["Retention"] = "Conservazione",
        ["Days to keep per kind of data (audit trail, outbox, logs, deleted records and files, tokens), a nightly job that deletes what is older and the admin page Retention to set them and delete now. New apps keep processed messages and tokens 14 days, import and export jobs 30, everything else until set."] = "Giorni di conservazione per tipo di dato (audit trail, outbox, log, record e file eliminati, token), un job notturno che elimina i dati più vecchi e la pagina di amministrazione Conservazione per impostarli ed eliminare subito. Le nuove app conservano i messaggi elaborati e i token per 14 giorni, i job di importazione ed esportazione per 30, tutto il resto finché non lo imposti.",
        ["Almost always: tables like the outbox, the audit trail and the mail log grow without end otherwise."] = "Quasi sempre: altrimenti tabelle come l'outbox, l'audit trail e il registro email crescono senza fine.",
        ["One page for every kind of data"] = "Una pagina per ogni tipo di dato",
        ["Modules and app code add their own data"] = "I moduli e il codice dell'app aggiungono i propri dati",
        ["Deleted data is gone, there is no archive"] = "I dati eliminati spariscono, non esiste un archivio",
        ["Folders and files of the organisation with preview, upload and per-folder permissions."] = "Cartelle e file dell'organizzazione con anteprima, caricamento e permessi per cartella.",
        ["When users share documents like on a drive."] = "Quando gli utenti condividono documenti come su un'unità di rete.",
        ["File manager with preview of nearly every type"] = "File manager con anteprima di quasi ogni tipo",
        ["Blob storage grows"] = "Lo storage blob cresce",
        ["Features and editions"] = "Funzionalità ed edizioni",
        ["Features switched per tenant, editions and the tenant administration of the host."] = "Funzionalità attivate per tenant, edizioni e l'amministrazione dei tenant dell'host.",
        ["Multi-tenant SaaS with plans."] = "SaaS multi-tenant con piani.",
        ["[RequiresFeature] and feature gates"] = "[RequiresFeature] e feature gate",
        ["Only useful with several tenants"] = "Utile solo con più tenant",
        ["Comments, tags, ratings and reactions"] = "Commenti, tag, valutazioni e reazioni",
        ["Comments, tags and star ratings for any entity, opted in per entity type."] = "Commenti, tag e valutazioni a stelle per qualsiasi entità, attivati per tipo di entità.",
        ["Content that people discuss or rate."] = "Contenuti che le persone discutono o valutano.",
        ["Ready-made components"] = "Componenti pronti all'uso",
        ["Each entity type has to be registered"] = "Ogni tipo di entità deve essere registrato",
        ["Webhooks"] = "Webhook",
        ["Outgoing webhooks: admins register endpoints that get signed events about entity changes, workflow transitions and the app's own events, with retries and a delivery log. With the samples, products send events."] = "Webhook in uscita: gli amministratori registrano endpoint che ricevono eventi firmati su modifiche alle entità, transizioni dei workflow ed eventi propri dell'app, con nuovi tentativi e un registro delle consegne. Con gli esempi, i prodotti inviano eventi.",
        ["When other systems (an ERP, n8n, Zapier) should hear about changes without polling."] = "Quando altri sistemi (un ERP, n8n, Zapier) devono essere informati delle modifiche senza polling.",
        ["Signed like the Standard Webhooks spec"] = "Firmati secondo la specifica Standard Webhooks",
        ["Retries, delivery log and redelivery"] = "Nuovi tentativi, registro delle consegne e riconsegna",
        ["Entity sets have to be opted in"] = "I set di entità devono essere attivati singolarmente",
        ["Receivers must be reachable over https"] = "I destinatari devono essere raggiungibili tramite https",
        ["Workflows and approvals"] = "Workflow e approvazioni",
        ["States and transitions per entity type, approvals by roles or users with deadlines, reminders and escalation, a history, the approvals inbox; declared in code. With the samples, products go through an approval."] =
            "Stati e transizioni per tipo di entità, approvazioni da parte di ruoli o utenti con scadenze, promemoria ed escalation, una cronologia, la casella delle approvazioni; dichiarati nel codice. Con gli esempi, i prodotti passano per un'approvazione.",
        ["When entities move through steps that people decide on, such as review and release."] = "Quando le entità attraversano passaggi su cui decidono le persone, come revisione e rilascio.",
        ["Guards by permission, role or condition"] = "Protezioni per permesso, ruolo o condizione",
        ["Buttons, timeline and inbox ready-made"] = "Pulsanti, timeline e casella in arrivo pronti all'uso",
        ["Each entity type has to be declared"] = "Ogni tipo di entità deve essere dichiarato",
        ["Elsa workflows"] = "Workflow Elsa",
        ["Elsa Workflows 3 in the api: its tables in the app's database, its api under /api/elsa for the permission Workflows.Elsa.Manage, activities and triggers for Coworkee workflows. Elsa Studio runs as its own app."] =
            "Elsa Workflows 3 nell'api: le sue tabelle nel database dell'app, la sua api in /api/elsa per il permesso Workflows.Elsa.Manage, attività e trigger per i workflow Coworkee. Elsa Studio gira come app a sé.",
        ["When administrators should build long running processes themselves, beyond the states declared in code."] = "Quando gli amministratori devono creare da soli processi di lunga durata, oltre agli stati dichiarati nel codice.",
        ["Visual designer (Elsa Studio)"] = "Designer visuale (Elsa Studio)",
        ["Starts from transitions, decisions and entity changes"] = "Si avvia da transizioni, decisioni e modifiche alle entità",
        ["Elsa brings many packages and its own tables"] = "Elsa porta molti pacchetti e tabelle proprie",
        ["Elsa Studio is a separate app to run"] = "Elsa Studio è un'app separata da avviare",
        ["Workflow designer"] = "Designer di workflow",
        ["Elsa Studio, the visual designer, as an app of its own in the app host: signs in at the auth server like the web app, lets in users with the permission Workflows.Elsa.Manage and works with the Elsa API of the api. The app's navigation links to it."] =
            "Elsa Studio, il designer visuale, come app a sé nell'app host: accede al server di autenticazione come l'app web, fa entrare gli utenti con il permesso Workflows.Elsa.Manage e lavora con l'API Elsa dell'api. La navigazione dell'app vi rimanda.",
        ["When administrators should draw their workflows instead of writing them in C#."] = "Quando gli amministratori devono disegnare i propri workflow invece di scriverli in C#.",
        ["Drag and drop designer with the Coworkee activities"] = "Designer drag and drop con le attività Coworkee",
        ["Same users and sign-in as the app"] = "Stessi utenti e stesso accesso dell'app",
        ["A third web app to run and deploy"] = "Una terza app web da avviare e distribuire",
        ["Extended attributes"] = "Attributi estesi",
        ["Free key/value attributes for any entity without schema changes (the Documents sample brings it anyway)."] = "Attributi chiave/valore liberi per qualsiasi entità senza modifiche allo schema (l'esempio Documents lo include comunque).",
        ["When users need fields you cannot foresee."] = "Quando gli utenti hanno bisogno di campi che non puoi prevedere.",
        ["No migration per field"] = "Nessuna migrazione per campo",
        ["Values are not typed columns"] = "I valori non sono colonne tipizzate",
        ["Search"] = "Ricerca",
        ["Elasticsearch index; the app host adds an Elasticsearch container."] = "Indice Elasticsearch; l'app host aggiunge un container Elasticsearch.",
        ["Full text search over many documents."] = "Ricerca full-text su molti documenti.",
        ["Facets, ranking, cursor paging"] = "Facet, ranking, paginazione a cursore",
        ["Elasticsearch needs memory"] = "Elasticsearch richiede memoria",
        ["The app decides what to index"] = "L'app decide cosa indicizzare",
        ["Integration events through the transactional outbox."] = "Eventi di integrazione tramite l'outbox transazionale.",
        ["When several apps or services react to each other's events."] = "Quando più app o servizi reagiscono agli eventi gli uni degli altri.",
        ["Reliable delivery through the outbox"] = "Consegna affidabile tramite l'outbox",
        ["Idempotent handlers through the inbox"] = "Handler idempotenti tramite l'inbox",
        ["RabbitMQ is one more container"] = "RabbitMQ è un container in più",
        ["No event bus."] = "Nessun bus di eventi.",
        ["Outbox and inbox, handlers in this app."] = "Outbox e inbox, handler in questa app.",
        ["RabbitMQ transport, container in the app host."] = "Trasporto RabbitMQ, container nell'app host.",
        ["Client entities"] = "Entità client",
        ["The browser keeps copies of OData sets marked [ClientEntity] and filters them locally. Entities of the spec with clientEntity switch it on."] = "Il browser conserva copie dei set OData contrassegnati con [ClientEntity] e li filtra localmente. Le entità della specifica con clientEntity lo attivano.",
        ["Lists users filter all day, up to some ten thousand rows."] = "Elenchi che gli utenti filtrano tutto il giorno, fino ad alcune decine di migliaia di righe.",
        ["Instant filtering, sorting, facets"] = "Filtro, ordinamento e facet istantanei",
        ["Fewer queries on the server"] = "Meno query sul server",
        ["Rows are kept on the device"] = "Le righe restano sul dispositivo",
        ["Not for millions of rows"] = "Non per milioni di righe",
        ["Keycloak"] = "Keycloak",
        ["Keycloak container as external sign-in, with a realm for the app."] = "Container Keycloak come accesso esterno, con un realm per l'app.",
        ["When users should sign in with an identity provider."] = "Quando gli utenti devono accedere con un identity provider.",
        ["Single sign-on ready to try"] = "Single sign-on pronto da provare",
        ["One more container"] = "Un container in più",
        ["Blob storage"] = "Storage blob",
        ["Where uploaded files and backups go."] = "Dove finiscono i file caricati e i backup.",
        ["Azure Blob when the app will run on Azure."] = "Azure Blob quando l'app girerà su Azure.",
        ["Same code for every provider"] = "Stesso codice per ogni provider",
        ["Azurite is one more container"] = "Azurite è un container in più",
        ["Folder .data/blobs next to src."] = "Cartella .data/blobs accanto a src.",
        ["Azure Blob Storage, Azurite emulator in the app host."] = "Azure Blob Storage, emulatore Azurite nell'app host.",
        ["AI provider"] = "Provider IA",
        ["Model provider of the assistant (with the AI assistant); changeable later on the AI page of the app."] = "Provider del modello dell'assistente (con l'assistente IA); modificabile in seguito nella pagina IA dell'app.",
        ["Anthropic, OpenAI, Gemini or Mistral with a key; OpenRouter for many models behind one key; Ollama or LM Studio to run locally without a key; Azure OpenAI when data must stay in your Azure tenant; openAICompatible for gateways and vLLM."] = "Anthropic, OpenAI, Gemini o Mistral con una chiave; OpenRouter per molti modelli dietro un'unica chiave; Ollama o LM Studio per l'esecuzione locale senza chiave; Azure OpenAI quando i dati devono restare nel tuo tenant Azure; openAICompatible per gateway e vLLM.",
        ["Same tools and audit with every provider"] = "Stessi strumenti e stesso audit con ogni provider",
        ["Ollama runs offline in a container"] = "Ollama funziona offline in un container",
        ["Small local models call tools less reliably"] = "I modelli locali piccoli chiamano gli strumenti in modo meno affidabile",
        ["Ollama needs several GB of disk and RAM"] = "Ollama richiede diversi GB di disco e RAM",
        ["Redis"] = "Redis",
        ["Redis container in the app host: SignalR backplane, shared presence, cache invalidation and sign-in sessions across instances."] = "Container Redis nell'app host: backplane SignalR, presenza condivisa, invalidazione della cache e sessioni di accesso tra le istanze.",
        ["As soon as an api or the web app runs in more than one instance; keep it for production-like development."] = "Non appena un'api o l'app web gira in più di un'istanza; mantienilo per uno sviluppo simile alla produzione.",
        ["Scale out without sticky state"] = "Scalare senza stato legato a un'istanza",
        ["Permission and setting changes reach every instance at once"] = "Le modifiche a permessi e impostazioni raggiungono subito ogni istanza",
        ["Sign-in sessions survive restarts of the web app"] = "Le sessioni di accesso sopravvivono ai riavvii dell'app web",
        ["Without it everything stays in each process, fine for a single instance"] = "Senza di esso tutto resta nel singolo processo, va bene per una sola istanza",
        ["Grafana"] = "Grafana",
        ["Grafana with Prometheus, Loki, Tempo and an OpenTelemetry collector in the app host: metrics, logs and traces of every service, the app database and ready dashboards. Sign-in with the app's administrator, or at the app's auth server for administrators of the system organisation."] = "Grafana con Prometheus, Loki, Tempo e un collector OpenTelemetry nell'app host: metriche, log e trace di ogni servizio, il database dell'app e dashboard pronte. Accesso con l'amministratore dell'app o, per gli amministratori dell'organizzazione di sistema, tramite il server di autenticazione dell'app.",
        ["Whenever you want to see how the app behaves: request rates, errors, latency, runtime, database and users at a glance."] = "Ogni volta che vuoi vedere come si comporta l'app: richieste, errori, latenza, runtime, database e utenti a colpo d'occhio.",
        ["Dashboards for requests, runtime, database and the app's data from the first start"] = "Dashboard per richieste, runtime, database e dati dell'app fin dal primo avvio",
        ["Metrics, logs and traces side by side and kept across sessions of the Aspire dashboard"] = "Metriche, log e trace affiancati e conservati tra le sessioni della dashboard di Aspire",
        ["Same sign-in as the app"] = "Stesso accesso dell'app",
        ["Five more containers (Grafana, Prometheus, Loki, Tempo, collector)"] = "Cinque container in più (Grafana, Prometheus, Loki, Tempo, collector)",
        ["Development only: a deployment brings its own monitoring"] = "Solo per lo sviluppo: un deployment porta il proprio monitoraggio",
        ["WebDataStudio"] = "WebDataStudio",
        ["Kibana"] = "Kibana",
        ["Kibana next to the Elasticsearch container, to look into the search indexes. Sign-in at the app's auth server through oauth2-proxy (with Keycloak when it is on); only administrators of the system organisation get in."] = "Kibana accanto al container Elasticsearch, per esaminare gli indici di ricerca. Accesso tramite il server di autenticazione dell'app con oauth2-proxy (con Keycloak se attivo); entrano solo gli amministratori dell'organizzazione di sistema.",
        ["When you want to see what the app indexed, try queries or watch the cluster while developing."] = "Quando vuoi vedere cosa ha indicizzato l'app, provare query o osservare il cluster durante lo sviluppo.",
        ["Discover, Dev Tools and index management on the app's indexes"] = "Discover, Dev Tools e gestione degli indici sugli indici dell'app",
        ["Same sign-in as the app, administrators only"] = "Stesso accesso dell'app, solo amministratori",
        ["Two more containers (Kibana, oauth2-proxy), Kibana needs about 1 GB of memory"] = "Due container in più (Kibana, oauth2-proxy); Kibana richiede circa 1 GB di memoria",
        ["Kibana sees every organisation's indexed data"] = "Kibana vede i dati indicizzati di tutte le organizzazioni",
        ["WebDataStudio, a database studio in the browser, connected to the app database. Sign-in with the app's administrator, or at the app's auth server for administrators of the system organisation."] = "WebDataStudio, uno studio per database nel browser, collegato al database dell'app. Accesso con l'amministratore dell'app o, per gli amministratori dell'organizzazione di sistema, tramite il server di autenticazione dell'app.",
        ["Whenever you want to look into the app database, run SQL or fix data while developing."] = "Ogni volta che vuoi esaminare il database dell'app, eseguire SQL o correggere dati durante lo sviluppo.",
        ["Tables, queries, charts and exports without a local database tool"] = "Tabelle, query, grafici ed esportazioni senza uno strumento di database locale",
        ["Development only: it has full access to the database"] = "Solo per lo sviluppo: ha accesso completo al database",
        ["Open WebUI"] = "Open WebUI",
        ["Open WebUI next to the Ollama container: a chat in the browser over the local models. Sign-in with the app's administrator, or at the app's auth server for administrators of the system organisation."] = "Open WebUI accanto al container Ollama: una chat nel browser con i modelli locali. Accesso con l'amministratore dell'app o, per gli amministratori dell'organizzazione di sistema, tramite il server di autenticazione dell'app.",
        ["When you want to try the local models in a chat, compare them or write prompts before the app uses them."] = "Quando vuoi provare i modelli locali in una chat, confrontarli o scrivere prompt prima che l'app li usi.",
        ["Chat with every model Ollama has, with history"] = "Chat con ogni modello di Ollama, con cronologia",
        ["One more container of about 4 GB"] = "Un container in più di circa 4 GB",
        ["Only with the Ollama provider"] = "Solo con il provider Ollama",
        ["AspireUI"] = "AspireUI",
        ["AirWorks client"] = "Client AirWorks",
        ["A second client next to the Blazor app: the AirWorks web desktop (TypeScript) with windows, taskbar and apps for nearly everything the Blazor app offers: settings, files, data, chat, reports with their designer, the assistant and the administration. Same sign-in (and Keycloak), same api, theme and logo of the app; runs in the Aspire app host."] = "Un secondo client accanto all'app Blazor: il desktop web AirWorks (TypeScript) con finestre, barra delle applicazioni e app per quasi tutto ciò che offre l'app Blazor: impostazioni, file, dati, chat, report con il loro designer, l'assistente e l'amministrazione. Stesso accesso (anche Keycloak), stessa api, tema e logo dell'app; gira nell'app host Aspire.",
        ["When users want a desktop-like workspace with several windows side by side, or the app needs a TypeScript client to extend."] = "Quando gli utenti vogliono uno spazio di lavoro simile a un desktop con più finestre affiancate, o l'app ha bisogno di un client TypeScript da estendere.",
        ["Library apps for settings, files with preview, data, chat, reports and the administration"] = "App della libreria per impostazioni, file con anteprima, dati, chat, report e amministrazione",
        ["Your own apps in TypeScript next to them"] = "Le tue app in TypeScript accanto a esse",
        ["Same users, permissions and data as the Blazor app"] = "Stessi utenti, permessi e dati dell'app Blazor",
        ["Needs Node.js to build"] = "Richiede Node.js per la build",
        ["A second client to keep up to date"] = "Un secondo client da mantenere aggiornato",
        ["AirWorks packages"] = "Pacchetti AirWorks",
        ["Where the AirWorks client takes @coworkee/client and @coworkee/airworks from: the tarballs inside the template (no npm registry needed for them) or npm in the version of the template."] = "Da dove il client AirWorks prende @coworkee/client e @coworkee/airworks: dai tarball inclusi nel template (senza bisogno di un registro npm) o da npm nella versione del template.",
        ["npm once the packages of the release are on npm and the app should update them like any other npm dependency."] = "npm quando i pacchetti della release sono su npm e l'app deve aggiornarli come qualsiasi altra dipendenza npm.",
        ["Bundled: works offline and right after a release"] = "Inclusi: funziona offline e subito dopo una release",
        ["npm: updates like other npm dependencies"] = "npm: aggiornamenti come le altre dipendenze npm",
        ["Bundled: the tarballs live in the app's repository"] = "Inclusi: i tarball risiedono nel repository dell'app",
        ["npm: needs the release on npmjs.com"] = "npm: richiede la release su npmjs.com",
        ["The tarballs inside the template, in ClientApp/vendor."] = "I tarball inclusi nel template, in ClientApp/vendor.",
        ["npm, the version of this template."] = "npm, la versione di questo template.",
        ["AirWorks app launcher"] = "Launcher di app AirWorks",
        ["How the start button of the AirWorks desktop shows the apps: the start menu sliding in from the side, or a full-screen grid of large icons over the blurred desktop with search and keyboard navigation. Coworkee:AirWorks:Launcher of the AirWorks host; users can switch it in the desktop settings."] = "Come il pulsante Start del desktop AirWorks mostra le app: il menu Start che scorre dal lato, oppure una griglia a schermo intero di icone grandi sopra il desktop sfocato, con ricerca e navigazione da tastiera. Coworkee:AirWorks:Launcher dell'host AirWorks; gli utenti possono cambiarlo nelle impostazioni del desktop.",
        ["Overlay when the app has many apps or is used on tablets and phones; the menu keeps the desktop visible."] = "Overlay quando l'app ha molte app o viene usata su tablet e smartphone; il menu lascia visibile il desktop.",
        ["Overlay: all apps at a glance, search as you type"] = "Overlay: tutte le app a colpo d'occhio, ricerca durante la digitazione",
        ["Menu: the desktop stays visible"] = "Menu: il desktop resta visibile",
        ["Overlay: covers the desktop while open"] = "Overlay: copre il desktop finché è aperto",
        ["The start menu slides in from the side."] = "Il menu Start scorre dal lato.",
        ["A full-screen app grid over the blurred desktop."] = "Una griglia di app a schermo intero sopra il desktop sfocato.",
        ["More about {0}"] = "Altro su {0}",
        ["Only used with {0}: switch it on first."] = "Usato solo con {0}: attivalo prima.",
        ["Only used with {0}: {1}."] = "Usato solo con {0}: {1}.",
        ["AspireUI, a web UI to host and try more apps and stacks next to the app, in the app host. Its apps show up on the admin page Services. Sign-in with the app's administrator, or at the app's auth server for administrators of the system organisation."] = "AspireUI, un'interfaccia web per ospitare e provare altre app e stack accanto all'app, nell'app host. Le sue app compaiono nella pagina di amministrazione Servizi. Accesso con l'amministratore dell'app o, per gli amministratori dell'organizzazione di sistema, tramite il server di autenticazione dell'app.",
        ["When the app should be tried next to other apps or stacks (a second service, a database tool, a sample), or the Services page should list them."] = "Quando l'app deve essere provata accanto ad altre app o stack (un secondo servizio, uno strumento di database, un esempio), o la pagina Servizi deve elencarli.",
        ["Start and stop more apps and stacks from one web UI"] = "Avvia e arresta altre app e stack da un'unica interfaccia web",
        ["The hosted apps show up on the admin page Services"] = "Le app ospitate compaiono nella pagina di amministrazione Servizi",
        ["Development only: it hosts whatever you give it"] = "Solo per lo sviluppo: ospita qualsiasi cosa gli dai",
        ["Database"] = "Database",
        ["Database engine of the app; the app host starts it and the initial migration is made for it."] = "Motore di database dell'app; l'app host lo avvia e la migrazione iniziale è creata per esso.",
        ["Postgres unless the organisation runs SQL Server (or Azure SQL); SQLite for demos, prototypes and installs on one machine."] = "Postgres, a meno che l'organizzazione usi SQL Server (o Azure SQL); SQLite per demo, prototipi e installazioni su un solo computer.",
        ["postgres: every module, database backups from the admin pages"] = "postgres: tutti i moduli, backup del database dalle pagine di amministrazione",
        ["sqlServer: fits Microsoft shops and Azure SQL"] = "sqlServer: adatto ad ambienti Microsoft e Azure SQL",
        ["sqlite: no container, the database is one file"] = "sqlite: nessun container, il database è un unico file",
        ["sqlServer: no backups from the admin pages, a heavy container"] = "sqlServer: nessun backup dalle pagine di amministrazione, un container pesante",
        ["sqlite: one writer at a time, background jobs kept in memory, no backups from the admin pages"] = "sqlite: un solo scrittore alla volta, job in background tenuti in memoria, nessun backup dalle pagine di amministrazione",
        ["PostgreSQL container in the app host."] = "Container PostgreSQL nell'app host.",
        ["SQL Server container in the app host."] = "Container SQL Server nell'app host.",
        ["SQLite file .data/<name>.db, no container."] = "File SQLite .data/<name>.db, nessun container.",
        ["Default theme of the installation."] = "Tema predefinito dell'installazione.",
        ["Pick the look closest to your brand; brand colors adjust it."] = "Scegli l'aspetto più vicino al tuo marchio; i colori del marchio lo adattano.",
        ["Twenty-one themes that differ in more than colors, also in where the logo sits"] = "Ventuno temi che differiscono non solo nei colori, ma anche nella posizione del logo",
        ["Organisations can still choose another"] = "Le organizzazioni possono comunque sceglierne un altro",
        ["Blue, humanist font, rounded."] = "Blu, carattere umanista, arrotondato.",
        ["Warm orange on paper."] = "Arancione caldo su carta.",
        ["MudBlazor purple."] = "Viola MudBlazor.",
