        ["The app is not set up yet: its setup page asks for this token."] = "L'app non è ancora configurata: la sua pagina di configurazione chiede questo token.",
        ["Neutral grays and blue, like a code hosting site."] = "Grigi neutri e blu, come un sito di hosting di codice.",
        ["Editor look: compact, dark gray with blue."] = "Aspetto da editor: compatto, grigio scuro con blu.",
        ["Cool polar blues and frost."] = "Blu polari freddi e brina.",
        ["Purple and pink on a night background."] = "Viola e rosa su uno sfondo notturno.",
        ["Warm cream and deep teal, serif headings."] = "Crema caldo e verde petrolio intenso, titoli con grazie.",
        ["Soft editor grays, blue and violet."] = "Grigi tenui da editor, blu e violetto.",
        ["Plain white paper, serif headings, flat."] = "Semplice carta bianca, titoli con grazie, piatto.",
        ["Aubergine app bar, green accents."] = "Barra dell'app color melanzana, accenti verdi.",
        ["Dark header with the logo, white pages, blue links, like GitHub."] = "Intestazione scura con il logo, pagine bianche, link blu, come GitHub.",
        ["Link page look: lime and violet, pill buttons, roomy."] = "Aspetto da pagina di link: lime e violetto, pulsanti a pillola, arioso.",
        ["Green on black like a shell, monospace, square, no logo."] = "Verde su nero come una shell, spaziatura fissa, squadrato, senza logo.",
        ["Dark sidebar with the logo next to light pages, indigo."] = "Barra laterale scura con il logo accanto a pagine chiare, indaco.",
        ["Amber on charcoal, dark header with the logo."] = "Ambra su antracite, intestazione scura con il logo.",
        ["Fresh mint and teal, roomy, the logo in the header."] = "Menta fresca e verde petrolio, arioso, il logo nell'intestazione.",
        ["Black and white, no shadows."] = "Bianco e nero, senza ombre.",
        ["Primary color"] = "Colore primario",
        ["Primary brand color #rrggbb. With a brand color the app gets its own theme (named like the title), based on the chosen theme, as default."] = "Colore primario del marchio #rrggbb. Con un colore del marchio l'app riceve come predefinito un tema proprio (con il nome del titolo), basato sul tema scelto.",
        ["When the app should carry the brand color."] = "Quando l'app deve portare il colore del marchio.",
        ["Contrast text is computed"] = "Il colore del testo a contrasto viene calcolato",
        ["The title must not be the name of a built-in theme"] = "Il titolo non deve essere il nome di un tema integrato",
        ["Secondary color"] = "Colore secondario",
        ["Secondary brand color #rrggbb."] = "Colore secondario del marchio #rrggbb.",
        ["Together with the primary color."] = "Insieme al colore primario.",
        ["Accent in buttons and links"] = "Accento in pulsanti e link",
        ["Logo file (svg, png, ...); the CLI copies it into the web client. It shows in the app bar, the browser tab and on the sign-in pages."] = "File del logo (svg, png, ...); la CLI lo copia nel client web. Compare nella barra dell'app, nella scheda del browser e nelle pagine di accesso.",
        ["Always for a real app."] = "Sempre per un'app reale.",
        ["One file for app, tab and sign-in"] = "Un solo file per app, scheda e accesso",
        ["SVG scales best"] = "SVG si ridimensiona meglio",
        ["Sign-in layout"] = "Layout di accesso",
        ["Layout of the sign-in pages."] = "Layout delle pagine di accesso.",
        ["Split for a full-page image or video, Card for a plain look."] = "Diviso per un'immagine o un video a tutta pagina, Scheda per un aspetto semplice.",
        ["Changeable later on the Themes page"] = "Modificabile in seguito nella pagina Temi",
        ["A centered card."] = "Una scheda centrata.",
        ["Image or video on one side, the form on the other."] = "Immagine o video da un lato, il modulo dall'altro.",
        ["A colored panel next to the form."] = "Un pannello colorato accanto al modulo.",
        ["Sign-in media"] = "Contenuto multimediale di accesso",
        ["Image or video next to the sign-in form: a local file (copied into the web client) or an http(s) address."] = "Immagine o video accanto al modulo di accesso: un file locale (copiato nel client web) o un indirizzo http(s).",
        ["With the Split or Slide layout."] = "Con il layout Diviso o Scorrevole.",
        ["With the Split or Slide layout, or as background of the loading screen."] = "Con il layout Diviso o Scorrevole, o come sfondo della schermata di caricamento.",
        ["Background of the app's loading screen while the WebAssembly app loads."] = "Sfondo della schermata di caricamento dell'app mentre l'app WebAssembly si carica.",
        ["SignInMedia to greet with the sign-in image or video already while loading."] = "SignInMedia per accogliere con l'immagine o il video di accesso già durante il caricamento.",
        ["Soft moving shapes in the theme's colours."] = "Forme in morbido movimento nei colori del tema.",
        ["The image or video of the sign-in pages."] = "L'immagine o il video delle pagine di accesso.",
        ["The theme's background colour only."] = "Solo il colore di sfondo del tema.",
        [".mp4, .webm, .ogg and .mov play as video"] = ".mp4, .webm, .ogg e .mov vengono riprodotti come video",
        ["Large videos slow the first sign-in"] = "I video grandi rallentano il primo accesso",
        ["Sign-in media side"] = "Lato del contenuto multimediale di accesso",
        ["Side of the sign-in media."] = "Lato del contenuto multimediale di accesso.",
        ["To match the media's composition."] = "Per adattarsi alla composizione del contenuto multimediale.",
        ["Media left."] = "Contenuto multimediale a sinistra.",
        ["Media right."] = "Contenuto multimediale a destra.",
        ["Default mapping of generated entities to their DTOs; an entity can choose its own."] = "Mapping predefinito delle entità generate sui loro DTO; un'entità può sceglierne uno proprio.",
        ["Mapperly for many or large entities."] = "Mapperly per molte entità o entità grandi.",
        ["manual: plain code you can read"] = "manual: codice semplice e leggibile",
        ["mapperly: compile-time mapper, reports unmapped members"] = "mapperly: mapper in fase di compilazione, segnala i membri non mappati",
        ["manual: one more line per property"] = "manual: una riga in più per proprietà",
        ["mapperly: one more package"] = "mapperly: un pacchetto in più",
        ["A ToDto extension method."] = "Un metodo di estensione ToDto.",
        ["A Mapperly mapper."] = "Un mapper Mapperly.",
        ["Languages the app offers from the start. 23 languages ship with the library; the others are machine translated at the first start with the translation service. Administrators switch more on later on the Languages page. Empty offers English and German."] = "Lingue che l'app offre fin dall'inizio. La libreria include 23 lingue; le altre vengono tradotte automaticamente al primo avvio con il servizio di traduzione. Gli amministratori ne attivano altre in seguito nella pagina Lingue. Vuoto offre inglese e tedesco.",
        ["When the users speak only some of the languages, or languages other than English and German."] = "Quando gli utenti parlano solo alcune delle lingue, o lingue diverse dall'inglese e dal tedesco.",
        ["Users see only languages that make sense"] = "Gli utenti vedono solo le lingue sensate",
        ["Any language the translation service knows"] = "Qualsiasi lingua conosciuta dal servizio di traduzione",
        ["Machine translations are good, not perfect: review them on the Translations page"] = "Le traduzioni automatiche sono buone, non perfette: rivedile nella pagina Traduzioni",
        ["English"] = "Inglese",
        ["Default language"] = "Lingua predefinita",
        ["Language of users who chose none and whose browser asks for none of the offered ones."] = "Lingua degli utenti che non ne hanno scelta nessuna e il cui browser non richiede nessuna di quelle offerte.",
        ["When most users speak another language than English."] = "Quando la maggior parte degli utenti parla una lingua diversa dall'inglese.",
        ["Right language at the first visit"] = "La lingua giusta fin dalla prima visita",
        ["Must be one of the languages"] = "Deve essere una delle lingue",
        ["Translation service"] = "Servizio di traduzione",
        ["Translates the texts a language lacks: at the first start, when a language is switched on, or on request. Changeable later in the settings (Translation)."] = "Traduce i testi mancanti in una lingua: al primo avvio, quando una lingua viene attivata o su richiesta. Modificabile in seguito nelle impostazioni (Traduzione).",
        ["LibreTranslate to start free and without an account, DeepL or Azure for the best quality, AI when the assistant's model should do it."] = "LibreTranslate per iniziare gratis e senza account, DeepL o Azure per la migliore qualità, IA quando deve occuparsene il modello dell'assistente.",
